{"content": "from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
from pydantic import BaseModel

app = FastAPI()

class CommonHeaders(BaseModel):
    my_header: str

@app.get("/no-convert")
async def read_root(headers: CommonHeaders = Header(convert_underscores=False)):
    return {"my_header": headers.my_header}

client = TestClient(app)

def test_no_convert():
    # Should accept underscore
    resp = client.get("/no-convert", headers={"my_header": "underscore"})
    print(f"No-convert underscore: {resp.json()}")

    # Should NOT accept hyphen
    resp = client.get("/no-convert", headers={"my-header": "hyphen"})
    print(f"No-convert hyphen: {resp.json()}")

if __name__ == "__main__":
    test_no_convert()
", "filepath": "test_no_convert.py"}

